    for i in range(len(xs) - 1):
        if not xs[i] < xs[i + 1]:
            return False
    return True


def binary_search(xs: list[int], x: int) -> int | None:
    """
    pre: is_strictly_ascending(xs)
    post: (__return__ is None) == (x not in xs)
    post: __return__ is None or (0 <= __return__ < len(xs) and xs[__return__] == x)
    """
    lo = 0
    hi = len(xs) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if xs[mid] == x:
            return mid
        if xs[mid] < x:
            lo = mid + 1
        else:
            hi = mid - 1
    return None

