    """
    Return the n-th Fibonacci number, with fib(0) = 0 and fib(1) = 1.

    pre: n >= 0
    post: fib_is_correct(n, __return__)
    """
    a, b = 0, 1
    for bit in bin(n)[2:]:
        c = a * (2 * b - a)
        d = a * a + b * b
        if bit == '1':
            a, b = d, c + d
        else:
            a, b = c, d
    return a

