def _is_rotation_of(result: list, original: list, k: int) -> bool:
    """Return True iff result equals original rotated left by k positions."""
    n = len(original)
    if len(result) != n:
        return False
    if n == 0:
        return True
    return all(result[i] == original[(i + k) % n] for i in range(n))


def rotate_left(xs: list[int], k: int) -> list[int]:
    """Rotate the list to the left by k positions: the first k elements move to the end.

    pre: 0 <= k <= len(xs)
    post: len(__return__) == len(xs)
    post: _is_rotation_of(__return__, xs, k)
    """
    n = len(xs)
    if n == 0:
        return []
    return xs[k:] + xs[:k]

